#!/usr/bin/env node

/**
 * Simple migration script
 *
 * - Reads all .sql files from ./migrations
 * - Sorts them alphabetically (which usually matches sequential migration IDs)
 * - Logs the filenames in the order they would be applied
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function main() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  const files = fs
    .readdirSync(MIGRATIONS_DIR)
    .filter((file) => file.endsWith('.sql'))
    .sort();

  if (files.length === 0) {
    console.log('No .sql migration files found.');
    return;
  }

  console.log('Migrations that would be applied (in order):');
  for (const file of files) {
    console.log(file);
  }
}

if (require.main === module) {
  main();
}

