#!/usr/bin/env node

/**
 * Simple migration runner
 *
 * Reads all .sql files from ./migrations, sorts them by filename,
 * resolves a DATABASE_URL and other values from .env.test, sends
 * them to the migration audit service, and logs the order in which
 * migrations would be applied. It does not actually connect to the DB.
 */

const fs = require('fs');
const path = require('path');
const http = require('http');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_TEST_PATH = path.join(__dirname, '.env.test');
const AUDIT_URL = 'http://localhost:47301/api/audit';

function loadEnvTest() {
  if (!fs.existsSync(ENV_TEST_PATH)) {
    console.error(`.env.test file not found at: ${ENV_TEST_PATH}`);
    process.exit(1);
  }

  const contents = fs.readFileSync(ENV_TEST_PATH, 'utf8');
  const lines = contents.split(/\r?\n/);
  const env = {};

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const [key, ...rest] = trimmed.split('=');
    if (!key) continue;
    const value = rest.join('=').trim();
    env[key] = value;
  }

  if (!env.DATABASE_URL) {
    console.error('DATABASE_URL not found in .env.test or has no value.');
    process.exit(1);
  }

  return env;
}

function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_URL);

    const payload = JSON.stringify(envVars);

    const options = {
      hostname: url.hostname,
      port: url.port || 80,
      path: url.pathname + url.search,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
      },
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit service logging successful.');
          resolve();
        } else {
          console.error(`Audit service responded with status ${res.statusCode}: ${data}`);
          reject(new Error(`Audit service error: ${res.statusCode}`));
        }
      });
    });

    req.on('error', (err) => {
      console.error('Failed to reach audit service:', err.message);
      reject(err);
    });

    req.write(payload);
    req.end();
  });
}

async function main() {
  const envVars = loadEnvTest();
  const databaseUrl = envVars.DATABASE_URL;

  console.log('Resolved DATABASE_URL from .env.test');
  console.log(`Pretending to connect to: ${databaseUrl}`);
  console.log('Sending connection details to migration audit service...');

  try {
    await sendAuditLog(envVars);
  } catch (err) {
    console.error('Aborting migrations due to audit logging failure.');
    process.exit(1);
  }

  console.log('Connection successful (simulated).');

  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  const entries = fs.readdirSync(MIGRATIONS_DIR, { withFileTypes: true });

  const sqlFiles = entries
    .filter((entry) => entry.isFile() && entry.name.endsWith('.sql'))
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

  if (sqlFiles.length === 0) {
    console.log('No .sql migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  sqlFiles.forEach((file) => {
    console.log(file);
  });
}

if (require.main === module) {
  main().catch((err) => {
    console.error('Unexpected error during migration:', err);
    process.exit(1);
  });
}

