// Directory containing migration SQL files
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function isSqlFile(fileName) {
  return fileName.toLowerCase().endsWith('.sql');
}

function getMigrationsInOrder(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  // Only include files (not subdirectories) that end with .sql
  const sqlFiles = entries
    .filter((entry) => entry.isFile() && isSqlFile(entry.name))
    .map((entry) => entry.name);

  // Sort lexicographically so files like 001_..., 002_... run in order
  sqlFiles.sort((a, b) => a.localeCompare(b));

  return sqlFiles;
}

function main() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  const migrations = getMigrationsInOrder(MIGRATIONS_DIR);

  if (migrations.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log('Migrations that would be applied, in order:');
  migrations.forEach((fileName, index) => {
    console.log(`${index + 1}. ${fileName}`);
  });
}

if (require.main === module) {
  main();
}

module.exports = { getMigrationsInOrder };

