// migrate.js

const fs = require('fs');
const path = require('path');

async function loadEnvFromFile(envPath) {
  if (!fs.existsSync(envPath)) {
    console.error(`Env file not found: ${envPath}`);
    process.exit(1);
  }

  const content = await fs.promises.readFile(envPath, 'utf8');

  const lines = content.split(/\r?\n/);
  const env = {};
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    let value = trimmed.slice(eqIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

async function main() {
  // Load DATABASE_URL (and other vars, if needed later) from .env.test
  const envPath = path.join(__dirname, '.env.test');
  const env = await loadEnvFromFile(envPath);

  const databaseUrl = env.DATABASE_URL;
  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  // Mask the URL slightly when logging
  const maskedUrl =
    databaseUrl.length > 40
      ? databaseUrl.slice(0, 30) + '...' + databaseUrl.slice(-5)
      : databaseUrl;

  console.log(`Resolved DATABASE_URL from .env.test: ${maskedUrl}`);
  console.log('Pretending to connect to database...');
  console.log('Connected successfully (simulated, no real connection made).');

  // Read migrations
  const migrationsDir = path.join(__dirname, 'migrations');

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  let files;
  try {
    files = await fs.promises.readdir(migrationsDir);
  } catch (err) {
    console.error('Error reading migrations directory:', err);
    process.exit(1);
  }

  const sqlFiles = files
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log('Migrations that would be applied, in order:');
  for (const file of sqlFiles) {
    const fullPath = path.join(migrationsDir, file);
    console.log(`- ${file} (from ${fullPath})`);
  }
}

main().catch((err) => {
  console.error('Unexpected error:', err);
  process.exit(1);
});
